{"source":"#include <stdio.h>

int main(int argc, char *argv[]){
    int n,m;
    int neg=0, pos=0;
    int temp;
    scanf("%d %d", &n ,&m);
    int l, r;
    for(int i=0; i<n; i++){
        scanf("%d", &temp);
        if (temp<0){
            neg++;

        }else{
            pos++;
        }
    }
    for (int i=0; i<m; i++){
        scanf("%d %d", &l,&r);
        int len = r - l + 1;
        if(len % 2 == 1){
            printf("0\n");
        }else{
            int half = len / 2;
            if (pos >= half && neg >= half){
                printf("1\n");
            }else{
                printf("0\n");
            }
        }
    }

    return 0;
}"}
